def _contract_result(
    operation: str,
    page_type: object,
    mode: object,
    *,
    contract_version: object = HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
    schema_version: object = HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
) -> tuple[HumanPageTemplateContract | None, dict[str, Any] | None]:
    mode_text = str(mode or "").strip()
    if mode_text not in HUMAN_PAGE_AUTHORING_MODES:
        return None, _failed(
            operation,
            "unknown-mode",
            f"未知人类页面编写模式：{mode_text}。",
            available=list(HUMAN_PAGE_AUTHORING_MODES),
        )
    try:
        contract_schema = int(schema_version)
    except (TypeError, ValueError):
        contract_schema = -1
    if (
        contract_schema != HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION
        or str(contract_version) != HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION
    ):
        return None, _failed(
            operation,
            "contract-version-incompatible",
            "人类页面模板合同版本不兼容。",
            actual={"schema_version": schema_version, "contract_version": contract_version},
            expected={
                "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
                "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
            },
        )
    try:
        return get_human_page_template(str(page_type or "")), None
    except CkbError as exc:  # get_human_page_template owns the stable type list.
        return None, _failed(operation, "unknown-page-type", str(exc))

def _section_slot(section: SectionContract) -> dict[str, str]:
    value = {"body": ""}
    if section.heading_pattern:
        value["heading"] = ""
    return value

def _resolve_within(path_value: str | Path, workspace_root: str | Path) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    candidate = Path(path_value)
    if not candidate.is_absolute():
        candidate = root / candidate
    candidate = candidate.resolve()
    if candidate != root and root not in candidate.parents:
        return None, _failed(
            "inspect",
            "path-outside-workspace",
            "页面路径越过 workspace_root。",
            path=str(candidate),
            workspace_root=str(root),
        )
    if not candidate.is_file():
        return None, _failed("inspect", "source-not-found", "页面来源不是可读取文件。", path=str(candidate))
    return candidate, None

def _document_sections(markdown: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    lines = markdown.splitlines()
    headings: list[dict[str, Any]] = []
    fence: str | None = None
    for index, line in enumerate(lines):
        stripped = line.lstrip()
        marker = stripped[:3]
        if marker in {"```", "~~~"}:
            if fence is None:
                fence = marker
            elif marker == fence:
                fence = None
            continue
        if fence is not None:
            continue
        match = _HEADING_RE.match(line.strip())
        if match:
            headings.append(
                {"level": len(match.group(1)), "text": match.group(2).strip(), "line": index + 1, "index": index}
            )
    sections: list[dict[str, Any]] = []
    for position, heading in enumerate(headings):
        end = len(lines)
        for following in headings[position + 1 :]:
            if int(following["level"]) <= int(heading["level"]):
                end = int(following["index"])
                break
        body = "\n".join(lines[int(heading["index"]) + 1 : end]).strip()
        sections.append({**heading, "body": body, "end_index": end})
    return headings, sections

def _matches(section: SectionContract, heading: Mapping[str, Any]) -> bool:
    if int(heading["level"]) != section.level:
        return False
    text = str(heading["text"])
    if section.heading_pattern:
        return re.fullmatch(section.heading_pattern, text) is not None
    return text == section.heading

def _managed_source(path: Path, workspace_root: Path) -> bool:
    relative = path.resolve().relative_to(workspace_root.resolve())
    return bool({"human", "markdown"} & set(relative.parts)) or path.suffix.casefold() in {
        ".sqlite",
        ".db",
    }

def _non_empty(value: Any) -> bool:
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (list, tuple, dict)):
        return bool(value)
    return value is not None

def _validate_top_level(payload: Mapping[str, Any], mode: str) -> dict[str, Any] | None:
    unknown = sorted(set(payload) - _MODE_FIELDS[mode])
    if unknown:
        return _failed(
            "render",
            "unknown-field",
            "schema 化输入包含未知字段。",
            fields=unknown,
        )
    return None

def _normalize_section_input(
    operation: str,
    section: SectionContract,
    value: Any,
) -> tuple[dict[str, str] | None, dict[str, Any] | None]:
    if not isinstance(value, Mapping):
        return None, _failed(operation, "field-type-invalid", "章节输入必须是对象。", field=f"sections.{section.section_id}")
    allowed = {"body", "heading"} if section.heading_pattern else {"body"}
    unknown = sorted(set(value) - allowed)
    if unknown:
        return None, _failed(
            operation,
            "unknown-field",
            "章节输入包含未知字段。",
            fields=[f"sections.{section.section_id}.{name}" for name in unknown],
        )
    body = str(value.get("body") or "").strip()
    heading = str(value.get("heading") or section.heading).strip()
    if section.heading_pattern and heading and re.fullmatch(section.heading_pattern, heading) is None:
        return None, _failed(
            operation,
            "heading-pattern-mismatch",
            "动态章节标题不符合冻结合同。",
            field=f"sections.{section.section_id}.heading",
            pattern=section.heading_pattern,
        )
    return {"body": body, "heading": heading}, None

def _base_missing_fields(payload: Mapping[str, Any], contract: HumanPageTemplateContract) -> list[str]:
    missing: list[str] = []
    evidence = payload.get("evidence")
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
    else:
        for field in contract.evidence_requirements.required_fields:
            if not _non_empty(evidence.get(field)):
                missing.append(f"evidence.{field}")
    context = payload.get("validation_context")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
    else:
        if contract.key_entity_budget.minimum and not _non_empty(context.get("key_entities")):
            missing.append("validation_context.key_entities")
        if contract.source_link_budget.minimum and not _non_empty(context.get("links")):
            missing.append("validation_context.links")
    return missing

def _load_source_for_render(
    payload: Mapping[str, Any], workspace_root: str | Path
) -> tuple[Path | None, str | None, dict[str, Any] | None]:
    source_value = payload.get("source_path")
    expected = str(payload.get("source_sha256") or "").casefold()
    missing = []
    if not _non_empty(source_value):
        missing.append("source_path")
    if not _SHA256_RE.fullmatch(expected):
        missing.append("source_sha256")
    if missing:
        return None, None, _missing("render", str(payload.get("page_type") or ""), str(payload.get("mode") or ""), missing)
    source, failure = _resolve_within(str(source_value), workspace_root)
    if failure:
        assert failure is not None
        failure["operation"] = "render"
        return None, None, failure
    assert source is not None
    try:
        markdown = source.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError) as exc:
        return None, None, _failed("render", "source-unreadable", f"页面来源读取失败：{exc}", path=str(source))
    actual = _sha256_text(markdown)
    if actual != expected:
        return None, None, _failed(
            "render",
            "target-drift",
            "页面来源在 inspect 后发生漂移。",
            expected_sha256=expected,
            actual_sha256=actual,
        )
    return source, markdown, None

def _validate_nested_input(
    operation: str,
    contract: HumanPageTemplateContract,
    evidence: Any,
    context: Any,
) -> dict[str, Any] | None:
    if not isinstance(evidence, Mapping):
        return None
    unknown_evidence = sorted(set(evidence) - set(contract.evidence_requirements.required_fields))
    if unknown_evidence:
        return _failed(
            operation,
            "unknown-field",
            "evidence 包含当前页面类型未定义的字段。",
            fields=[f"evidence.{field}" for field in unknown_evidence],
        )
    if not isinstance(context, Mapping):
        return None
    unknown_context = sorted(set(context) - _CONTEXT_FIELDS)
    if unknown_context:
        return _failed(
            operation,
            "unknown-field",
            "validation_context 包含未知字段。",
            fields=[f"validation_context.{field}" for field in unknown_context],
        )
    entries = (
        ("links", {"target", "purpose", "kind"}),
        ("current_facts", {"claim", "source", "observed_at"}),
    )
    for field, allowed in entries:
        value = context.get(field, [])
        if not isinstance(value, list):
            continue
        for index, item in enumerate(value):
            if not isinstance(item, Mapping):
                continue
            unknown = sorted(set(item) - allowed)
            if unknown:
                return _failed(
                    operation,
                    "unknown-field",
                    f"validation_context.{field} 条目包含未知字段。",
                    fields=[f"validation_context.{field}[{index}].{name}" for name in unknown],
                )
    return None

def _candidate_validation(
    contract: HumanPageTemplateContract,
    markdown: str,
    *,
    evidence: Any,
    context: Any,
    declared_boundary: Any,
) -> dict[str, Any]:
    missing: list[str] = []
    if not isinstance(evidence, Mapping):
        missing.append("evidence")
        evidence = {}
    for field in contract.evidence_requirements.required_fields:
        if not _non_empty(evidence.get(field)):
            missing.append(f"evidence.{field}")
    if not isinstance(context, Mapping):
        missing.append("validation_context")
        context = {}
    if missing:
        return _missing("validate", contract.page_type, "candidate", missing)

    base = validate_human_page(
        contract.page_type,
        markdown,
        context=context,
        contract_version=HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        schema_version=HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    )
    errors = list(base.get("errors", []))
    boundary_text = str(declared_boundary or "").strip()
    boundary_status = "passed"
    if boundary_text and boundary_text != contract.applicability_boundary:
        boundary_status = "failed"
        errors.append(
            _error(
                "applicability-boundary-drift",
                "输入适用边界与当前页面合同不一致。",
                expected=contract.applicability_boundary,
                actual=boundary_text,
            )
        )

    reasons = {str(error.get("reason")) for error in errors}

    def status_for(category: set[str]) -> str:
        return "failed" if reasons & category else "passed"

    checks = {
        "structure": {"status": status_for(_STRUCTURE_REASONS)},
        "budget": {
            "status": status_for(_BUDGET_REASONS),
            "key_entity_count": base.get("metrics", {}).get("key_entity_count"),
            "source_link_count": base.get("metrics", {}).get("source_link_count"),
        },
        "links": {"status": status_for(_LINK_REASONS)},
        "current_fact_evidence": {
            "status": status_for(_CURRENT_FACT_REASONS),
            "verified_count": base.get("metrics", {}).get("verified_current_fact_count"),
        },
        "contract_evidence": {
            "status": "passed",
            "required_fields": list(contract.evidence_requirements.required_fields),
        },
        "applicability_boundary": {
            "status": boundary_status,
            "value": contract.applicability_boundary,
        },
    }
    unclassified = reasons - _STRUCTURE_REASONS - _BUDGET_REASONS - _LINK_REASONS - _CURRENT_FACT_REASONS - {
        "applicability-boundary-drift"
    }
    if unclassified:
        checks["validation_context"] = {"status": "failed", "reasons": sorted(unclassified)}
    else:
        checks["validation_context"] = {"status": "passed"}
    return {
        "checks": checks,
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "errors": errors,
        "metrics": base.get("metrics", {}),
        "operation": "validate",
        "page_type": contract.page_type,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
    }

def validate_page_author(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Validate structure, budgets, links, evidence, and boundary in one result."""

    if not isinstance(payload, Mapping):
        return _failed("validate", "input-not-object", "validate 输入必须是 JSON 对象。")
    unknown = sorted(set(payload) - _VALIDATE_FIELDS)
    if unknown:
        return _failed(
            "validate",
            "unknown-field",
            "validate 输入包含未知字段。",
            fields=unknown,
        )
    contract, failure = _contract_result(
        "validate",
        payload.get("page_type"),
        "new",
        contract_version=payload.get("contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
        schema_version=payload.get("schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
    )
    if failure:
        return failure
    assert contract is not None
    failure = _validate_nested_input(
        "validate", contract, payload.get("evidence"), payload.get("validation_context")
    )
    if failure:
        return failure
    markdown = payload.get("markdown")
    if not isinstance(markdown, str) or not markdown.strip():
        return _missing("validate", contract.page_type, "candidate", ["markdown"])
    return _candidate_validation(
        contract,
        markdown,
        evidence=payload.get("evidence"),
        context=payload.get("validation_context"),
        declared_boundary=payload.get("applicability_boundary"),
    )

def _package_route(page_type: str) -> dict[str, Any]:
    if page_type in _RECORD_TYPES:
        return {
            "entrypoint": "record",
            "command": [
                "ckb.py",
                "record",
                "--out",
                "OUTPUT",
                "--kind",
                page_type,
                "--title",
                "TITLE",
                "--body",
                "BODY.md",
                "--from-pack",
                "PACK.json",
            ],
        }
    if page_type == "reference":
        return {
            "entrypoint": "reference",
            "command": ["ckb.py", "reference", "review", "--out", "OUTPUT", "--review", "REVIEW.json"],
        }
    if page_type == "feedback":
        return {
            "entrypoint": "feedback",
            "command": [
                "ckb.py",
                "feedback",
                "create",
                "--out",
                "OUTPUT",
                "--target",
                "TARGET",
                "--start-line",
                "START",
                "--end-line",
                "END",
                "--comment",
                "BODY.md",
                "--author",
                "AUTHOR",
            ],
        }
    if page_type == "learning-note":
        return {
            "entrypoint": "learning-note-generator",
            "plugin_command": "Ask about selection and save to daily learning note",
        }
    if page_type == "README":
        return {
            "entrypoint": "README-submit",
            "submission": "提交 BODY.md 供发布包 README 人工审阅；不写生成投影。",
        }
    if page_type in _NAVIGATION_TYPES:
        return {
            "entrypoint": f"{page_type}-generator",
            "command": ["ckb.py", "human-refresh", "--out", "OUTPUT"],
        }
    if page_type == "responsibility":
        return {
            "entrypoint": "responsibility-generator",
            "command": [
                "ckb.py",
                "review-pack",
                "--out",
                "OUTPUT",
                "--pack",
                "PACK_ID",
                "--review",
                "REVIEW.json",
            ],
        }
    raise RuntimeError(f"unrouted human page type: {page_type}")

def _staging_target(
    staging_dir: str | Path, workspace_root: str | Path
) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    target = Path(staging_dir)
    if not target.is_absolute():
        target = root / target
    target = target.resolve()
    if target == root or root not in target.parents:
        return None, _failed(
            "package",
            "path-outside-workspace",
            "staging 路径必须是 workspace_root 内的新目录。",
            path=str(target),
            workspace_root=str(root),
        )
    relative = target.relative_to(root)
    forbidden = {"human", "markdown", "machine"} & {part.casefold() for part in relative.parts}
    if forbidden or target.suffix.casefold() in {".sqlite", ".db"}:
        return None, _failed(
            "package",
            "managed-target-forbidden",
            "staging 包不得写入 human、markdown、machine 或 SQLite 受管路径。",
            path=str(target),
        )
    if target.exists():
        return None, _failed(
            "package",
            "staging-target-exists",
            "staging 包目录已存在；为避免覆盖，必须使用新目录。",
            path=str(target),
        )
    return target, None

def load_authoring_input(path: Path) -> Mapping[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, Mapping):
        raise ValueError("page-author input must be a JSON object")
    return value

def _validated_output(output: Path) -> Path:
    resolved = output.resolve()
    if not (resolved / "state.json").is_file():
        raise CkbError(f"template proposals require an existing CKB output with state.json: {resolved}")
    return resolved

def _expect_object(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise CkbError(f"template proposal {label} must be one JSON object")
    return dict(value)

def _expect_fields(value: Mapping[str, Any], expected: set[str], label: str) -> None:
    actual = set(value)
    unknown = sorted(actual - expected)
    missing = sorted(expected - actual)
    if unknown:
        raise CkbError(f"template proposal {label} contains unknown fields: {unknown}")
    if missing:
        raise CkbError(f"template proposal {label} is missing required fields: {missing}")

def _text(value: Any, label: str, *, maximum: int = 4000) -> str:
    if not isinstance(value, str) or not value.strip():
        raise CkbError(f"template proposal {label} must be non-empty text")
    normalized = value.strip()
    if len(normalized) > maximum or "\x00" in normalized:
        raise CkbError(f"template proposal {label} exceeds its text boundary")
    return normalized

def _string_list(value: Any, label: str, *, allow_empty: bool = False) -> list[str]:
    if not isinstance(value, list) or (not value and not allow_empty):
        suffix = "a list" if allow_empty else "a non-empty list"
        raise CkbError(f"template proposal {label} must be {suffix} of text values")
    result = [_text(item, f"{label}[{index}]", maximum=1000) for index, item in enumerate(value)]
    if len(result) != len(set(result)):
        raise CkbError(f"template proposal {label} contains duplicate values")
    return result

def _boolean(value: Any, label: str) -> bool:
    if not isinstance(value, bool):
        raise CkbError(f"template proposal {label} must be boolean")
    return value

def _integer(value: Any, label: str, *, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"template proposal {label} must be an integer between {minimum} and {maximum}")
    return value

def _semantic_version(value: Any, label: str = "version") -> str:
    normalized = _text(value, label, maximum=32)
    if not _SEMVER.fullmatch(normalized):
        raise CkbError(f"template proposal {label} must use MAJOR.MINOR.PATCH")
    return normalized

def _semantic_version_key(value: str) -> tuple[int, int, int]:
    matched = _SEMVER.fullmatch(value)
    if matched is None:
        raise CkbError(f"stored template proposal has an invalid version: {value}")
    return tuple(int(part) for part in matched.groups())  # type: ignore[return-value]

def _template_name(value: Any) -> str:
    normalized = _text(value, "template_name", maximum=80)
    if any(character in normalized for character in ("/", "\\", "\r", "\n", "\t")) or normalized in {".", ".."}:
        raise CkbError("template proposal template_name must be one path-independent name")
    builtin = {name.casefold(): name for name in list_human_page_types()}
    conflict = builtin.get(normalized.casefold())
    if conflict is not None:
        raise CkbError(f"template proposal cannot override or weaken builtin template: {conflict}")
    return normalized

def _target_document() -> dict[str, Any]:
    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "registry_id": HUMAN_PAGE_TEMPLATE_REGISTRY_ID,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    }

def _validate_target(value: Any) -> dict[str, Any]:
    target = _expect_object(value, "target")
    _expect_fields(target, _TARGET_FIELDS, "target")
    expected = _target_document()
    if target != expected:
        raise CkbError(
            "template proposal target drift: expected the current read-only builtin registry "
            f"{expected}, received {target}"
        )
    return expected

def _normalize_fields(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value:
        raise CkbError("template proposal fields must be a non-empty list")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        field = _expect_object(item, f"fields[{index}]")
        _expect_fields(field, _FIELD_FIELDS, f"fields[{index}]")
        field_id = _text(field["field_id"], f"fields[{index}].field_id", maximum=64)
        if not _IDENTIFIER.fullmatch(field_id):
            raise CkbError(f"template proposal fields[{index}].field_id has an invalid identifier")
        value_type = _text(field["value_type"], f"fields[{index}].value_type", maximum=16)
        if value_type not in _VALUE_TYPES:
            raise CkbError(f"template proposal fields[{index}].value_type must be one of {sorted(_VALUE_TYPES)}")
        result.append(
            {
                "field_id": field_id,
                "label": _text(field["label"], f"fields[{index}].label", maximum=120),
                "purpose": _text(field["purpose"], f"fields[{index}].purpose"),
                "required": _boolean(field["required"], f"fields[{index}].required"),
                "value_type": value_type,
            }
        )
    identifiers = [item["field_id"] for item in result]
    if len(identifiers) != len({value.casefold() for value in identifiers}):
        raise CkbError("template proposal fields contain duplicate field_id values")
    if not any(item["required"] for item in result):
        raise CkbError("template proposal must retain at least one required field")
    return result

def _normalize_sections(value: Any, field_ids: set[str]) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value:
        raise CkbError("template proposal sections must be a non-empty list")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        section = _expect_object(item, f"sections[{index}]")
        _expect_fields(section, _SECTION_FIELDS, f"sections[{index}]")
        section_id = _text(section["section_id"], f"sections[{index}].section_id", maximum=64)
        if not _IDENTIFIER.fullmatch(section_id):
            raise CkbError(f"template proposal sections[{index}].section_id has an invalid identifier")
        section_fields = _string_list(section["field_ids"], f"sections[{index}].field_ids")
        unknown = sorted(set(section_fields) - field_ids)
        if unknown:
            raise CkbError(f"template proposal sections[{index}] references unknown fields: {unknown}")
        result.append(
            {
                "field_ids": section_fields,
                "heading": _text(section["heading"], f"sections[{index}].heading", maximum=120),
                "purpose": _text(section["purpose"], f"sections[{index}].purpose"),
                "required": _boolean(section["required"], f"sections[{index}].required"),
                "section_id": section_id,
            }
        )
    identifiers = [item["section_id"] for item in result]
    if len(identifiers) != len({value.casefold() for value in identifiers}):
        raise CkbError("template proposal sections contain duplicate section_id values")
    if not any(item["required"] for item in result):
        raise CkbError("template proposal must retain at least one required section")
    referenced = {field_id for item in result for field_id in item["field_ids"]}
    missing = sorted(field_ids - referenced)
    if missing:
        raise CkbError(f"template proposal fields must be owned by at least one section: {missing}")
    return result

def _normalize_examples(value: Any, *, failures: bool) -> list[dict[str, Any]]:
    label = "failure_examples" if failures else "examples"
    expected_fields = _FAILURE_EXAMPLE_FIELDS if failures else _EXAMPLE_FIELDS
    if not isinstance(value, list) or not value:
        raise CkbError(f"template proposal requires at least one {label}")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        example = _expect_object(item, f"{label}[{index}]")
        _expect_fields(example, expected_fields, f"{label}[{index}]")
        normalized: dict[str, Any] = {
            "content": _text(example["content"], f"{label}[{index}].content", maximum=20_000),
            "name": _text(example["name"], f"{label}[{index}].name", maximum=120),
        }
        if failures:
            normalized["expected_errors"] = _string_list(
                example["expected_errors"], f"{label}[{index}].expected_errors"
            )
        else:
            expected_result = _text(example["expected_result"], f"{label}[{index}].expected_result", maximum=32)
            if expected_result != "passed":
                raise CkbError(f"template proposal {label}[{index}].expected_result must be passed")
            normalized["expected_result"] = expected_result
        result.append(normalized)
    names = [item["name"].casefold() for item in result]
    if len(names) != len(set(names)):
        raise CkbError(f"template proposal {label} contains duplicate names")
    return result
